import{_ as d,o as r,c as o,a2 as a}from"./chunks/framework.CRFziyHp.js";const b=JSON.parse('{"title":"布局导航组件","description":"","frontmatter":{"prev":{"text":"基础元素组件","link":"/features/ui-editor/components-basic"},"next":{"text":"信息展示组件","link":"/features/ui-editor/components-display"}},"headers":[],"relativePath":"features/ui-editor/components-layout.md","filePath":"features/ui-editor/components-layout.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/components-layout.md"};function n(l,t,s,i,h,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="布局导航组件" tabindex="-1">布局导航组件 <a class="header-anchor" href="#布局导航组件" aria-label="Permalink to &quot;布局导航组件&quot;">​</a></h1><p>本篇介绍 <strong>布局导航</strong> 分类下的 5 个组件：<strong>轮播图</strong>、<strong>图片布局</strong>、<strong>金刚区</strong>、<strong>搜索栏</strong>、<strong>筛选标签</strong>。它们负责首页顶部的视觉焦点、快捷入口与内容筛选。</p><div class="tip custom-block"><p class="custom-block-title">通用说明</p><p>组件宽高、外边距等请在选中组件后切换到 <strong>样式</strong> Tab 调整。各图片项、导航项的 <strong>点击动作</strong> 配置方式见 <a href="/features/ui-editor/styles-and-actions#点击动作-clickaction">样式与点击动作 — 点击动作</a>。</p></div><hr><h2 id="轮播图" tabindex="-1">轮播图 <a class="header-anchor" href="#轮播图" aria-label="Permalink to &quot;轮播图&quot;">​</a></h2><p><strong>组件说明：</strong> 多张图片自动或手动轮播，常用于首页顶部 Banner。</p><h3 id="适用页面" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子、服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>布局导航 → 轮播图</strong></li><li>在 <strong>图片列表</strong> 中点 <strong>+ 添加图片</strong>，从媒体库选择</li><li>为每张图单独设置 <strong>点击动作</strong>（如活动页、外链）</li><li>在 <strong>样式 → 高度</strong> 设置轮播区域高度（常用 <code>300～360</code> rpx）</li></ol><h3 id="属性配置" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>图片列表</td><td>轮播项，每项含图片与点击动作</td><td>2～5 张活动图</td></tr><tr><td>图片模式</td><td>单张图的填充方式</td><td>aspectFill（裁剪填充，常用）</td></tr><tr><td>图片圆角</td><td>每张图的圆角，rpx</td><td><code>0</code>、<code>16</code></td></tr><tr><td>轮播间隔</td><td>自动切换间隔，毫秒</td><td><code>3000</code>（3 秒）</td></tr><tr><td>动画时长</td><td>切换动画时长，毫秒</td><td><code>500</code></td></tr><tr><td>自动播放</td><td>是否自动轮播</td><td>开启</td></tr><tr><td>循环</td><td>播到最后一张后回到第一张</td><td>开启</td></tr><tr><td>纵向</td><td>纵向滑动轮播（少见）</td><td>一般关闭</td></tr><tr><td>显示指示器</td><td>底部小圆点/条</td><td>开启</td></tr><tr><td>指示器位置</td><td>在轮播内部或外部</td><td>内部 / 外部</td></tr><tr><td>指示器对齐</td><td>指示器水平位置</td><td>左 / 中 / 右</td></tr><tr><td>指示器默认颜色</td><td>未选中点颜色</td><td>半透明白 <code>#ffffff66</code></td></tr><tr><td>指示器激活颜色</td><td>当前页指示点颜色</td><td><code>#ffffff</code></td></tr><tr><td>指示器底部距离</td><td>距轮播底部的距离，rpx</td><td><code>20</code></td></tr><tr><td>指示器左右边距</td><td>指示器区域左右留白</td><td><code>0</code></td></tr><tr><td>指示器宽 / 高</td><td>单个指示点尺寸，rpx</td><td><code>12</code> × <code>12</code></td></tr><tr><td>指示器激活宽度</td><td>当前项可拉长为条</td><td>留空同默认宽度；<code>24</code></td></tr><tr><td>指示器圆角 / 间距</td><td>指示点形状与间隔</td><td>圆角 <code>6</code>、间距 <code>8</code></td></tr></tbody></table><h3 id="样式建议" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>首页首屏：高度 <strong>320～400</strong> rpx，左右 <strong>margin</strong> 各 <code>24</code> rpx + 圆角 <strong>16</strong> rpx</li><li>指示器选 <strong>内部 + 居中</strong>，浅色 Banner 用半透明白点</li><li>图片比例建议统一（如 2:1），避免切换时跳动</li></ul><h3 id="使用技巧-注意事项" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>至少添加 <strong>1 张</strong> 图片；仅 1 张时可关闭自动播放</li><li>每张图务必配置 <strong>点击动作</strong>，否则点击无效果</li><li>图片过多会增加首屏加载时间，建议 <strong>≤5 张</strong> 并压缩体积</li><li>关闭 <strong>显示指示器</strong> 时，用户难以感知可滑动，单图场景可关</li></ul><hr><h2 id="图片布局" tabindex="-1">图片布局 <a class="header-anchor" href="#图片布局" aria-label="Permalink to &quot;图片布局&quot;">​</a></h2><p><strong>组件说明：</strong> 按预设模板将 2～4 张图片拼成一块区域，适合活动入口、分类导购。</p><h3 id="适用页面-1" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-1" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子、服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加-1" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-1" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>布局导航 → 图片布局</strong></li><li>先选 <strong>布局模式</strong>，再按提示数量添加图片</li><li>在 <strong>样式 → 高度</strong> 设置整体高度（未设时默认约 <strong>400</strong> rpx）</li></ol><h3 id="属性配置-1" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-1" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>图片列表</td><td>各槽位图片及点击动作</td><td>见下方布局模式所需张数</td></tr><tr><td>布局模式</td><td>拼图样式</td><td>见下表</td></tr><tr><td>间距</td><td>图片之间的空隙，rpx</td><td><code>20</code>（默认）、<code>12</code>（紧凑）</td></tr><tr><td>圆角</td><td>整块与各图的圆角，rpx</td><td><code>16</code></td></tr><tr><td>内部圆角</td><td>拼接处是否圆角</td><td>自动 / 显示 / 隐藏</td></tr></tbody></table><p><strong>布局模式对照：</strong></p><table tabindex="0"><thead><tr><th>模式编号</th><th>名称</th><th>需要图片数</th><th>布局示意</th></tr></thead><tbody><tr><td>1</td><td>左大右二</td><td>3 张</td><td>左侧一大块，右侧上下两块</td></tr><tr><td>2</td><td>左大右混</td><td>4 张</td><td>左侧一大块，右上长条 + 右下两格</td></tr><tr><td>3</td><td>左右对分</td><td>2 张</td><td>左右各一块等大</td></tr><tr><td>4</td><td>三列等宽</td><td>3 张</td><td>横排三等分</td></tr></tbody></table><h3 id="样式建议-1" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-1" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>模式 1、2 适合 <strong>一主多辅</strong> 的运营位（主图放活动，辅图放次要入口）</li><li>模式 3 适合 <strong>双入口对比</strong>；模式 4 适合 <strong>三个并列分类</strong></li><li>高度固定为 <strong>350～450</strong> rpx，避免不同设备上布局抖动</li></ul><h3 id="使用技巧-注意事项-1" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-1" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>当前布局需要几张图，编辑器会提示 <strong>「x/y 张」</strong>；不足的位置显示占位 <strong>+</strong></li><li><strong>内部圆角 → 自动</strong>：间距为 0 时隐藏内侧圆角，有间距时显示</li><li>每张图可单独设 <strong>点击动作</strong></li><li>图片主体尽量居中，显示为 <strong>裁剪填充</strong>，避免重要内容被裁切</li></ul><hr><h2 id="金刚区" tabindex="-1">金刚区 <a class="header-anchor" href="#金刚区" aria-label="Permalink to &quot;金刚区&quot;">​</a></h2><p><strong>组件说明：</strong> 图标 + 文字的宫格快捷入口，类似 App 首页「分类图标」。</p><h3 id="适用页面-2" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-2" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子、服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加-2" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-2" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>布局导航 → 金刚区</strong></li><li>点 <strong>+ 添加项目</strong>，为每项上传 <strong>图标</strong>、填写 <strong>标签</strong>、设置 <strong>点击动作</strong></li><li>调整 <strong>每行列数</strong> 与图标大小</li></ol><h3 id="属性配置-2" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-2" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>导航项目</td><td>每项含图标、标签、点击动作</td><td>8～10 个常用功能</td></tr><tr><td>每行列数</td><td>一行显示几个</td><td><code>4</code>（常见）、<code>5</code>（更密）、<code>3</code>（更疏）</td></tr><tr><td>行间距</td><td>多行之间的垂直距离，rpx</td><td><code>30</code></td></tr><tr><td>第二行</td><td>是否允许显示第二行</td><td>项目超过列数时自动换行</td></tr><tr><td>隐藏文字</td><td>只显示图标</td><td>极简风格时可开</td></tr><tr><td>图标大小</td><td>图标边长，rpx</td><td><code>80</code></td></tr><tr><td>图标圆角</td><td>图标容器圆角</td><td><code>16</code>（方角图标）、<code>999</code>（圆形）</td></tr><tr><td>图标文字间距</td><td>图标与标签距离</td><td><code>16</code></td></tr><tr><td>文字大小</td><td>标签字号，rpx</td><td><code>24</code></td></tr><tr><td>文字颜色</td><td>标签颜色</td><td><code>#333333</code></td></tr><tr><td>文字字重</td><td>标签粗细</td><td>正常 / 中等</td></tr><tr><td>角标背景</td><td>项目角标底色（若业务有角标）</td><td>品牌强调色</td></tr></tbody></table><h3 id="样式建议-2" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-2" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>首页常用 <strong>4 列 × 2 行 = 8 个</strong> 入口，图标风格统一（线性或面性一致）</li><li>图标尺寸 <strong>72～88</strong> rpx，标签 <strong>2～4 个汉字</strong></li><li>整块区域上下 <strong>margin</strong> <code>20</code> rpx，与轮播、列表留出呼吸感</li></ul><h3 id="使用技巧-注意事项-2" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-2" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>每个项目必须配置 <strong>点击动作</strong>，否则点击无效</li><li>标签不宜过长，超出会换行或挤压布局</li><li><strong>隐藏文字</strong> 适合用户已熟悉的图标，新功能建议保留文字</li><li>自定义页常通过金刚区入口进入，记得目标页已 <strong>启用</strong> 对应配置</li></ul><hr><h2 id="搜索栏" tabindex="-1">搜索栏 <a class="header-anchor" href="#搜索栏" aria-label="Permalink to &quot;搜索栏&quot;">​</a></h2><p><strong>组件说明：</strong> 带搜索图标、提示文字与可选「搜一搜」按钮、更多入口的搜索条。</p><h3 id="适用页面-3" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-3" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th></tr></thead><tbody><tr><td>应用首页、功能页面、自定义页面</td><td>✅</td></tr><tr><td>社区圈子、服务表单</td><td>❌</td></tr></tbody></table><h3 id="如何添加-3" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-3" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>布局导航 → 搜索栏</strong></li><li>配置 <strong>提示文字</strong> 与搜索框外观</li><li>设置 <strong>搜索框点击</strong>、<strong>更多按钮点击</strong> 的跳转目标</li></ol><h3 id="属性配置-3" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-3" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>左侧图标展示方式</td><td>搜索图标用字体或图片</td><td>字体图标（默认）/ 图片</td></tr><tr><td>搜索图标名</td><td>字体图标名称</td><td><code>search</code>，可点 <strong>选择</strong></td></tr><tr><td>搜索图标前缀</td><td>特殊图标库前缀</td><td>一般留空</td></tr><tr><td>搜索图标颜色</td><td>图标颜色</td><td><code>#999999</code></td></tr><tr><td>搜索图标图片</td><td>图片模式下的 URL</td><td>品牌搜索 icon</td></tr><tr><td>图标边长</td><td>左侧图标尺寸，rpx</td><td><code>32</code></td></tr><tr><td>提示文字</td><td>输入框占位文案</td><td><code>搜索笔记、圈子、用户</code></td></tr><tr><td>提示字号 / 颜色 / 字重</td><td>占位文字样式</td><td><code>26</code>、<code>#999</code>、正常</td></tr><tr><td>提示对齐</td><td>占位文字对齐</td><td>左对齐 / 居中</td></tr><tr><td>按钮文字</td><td>右侧「搜一搜」文案</td><td><code>搜一搜</code>、<code>搜索</code></td></tr><tr><td>按钮背景 / 文字颜色</td><td>右侧按钮配色</td><td>黑底 <code>#000</code> + 白字</td></tr><tr><td>按钮字号 / 圆角</td><td>右侧按钮样式</td><td><code>26</code>、圆角 <code>50</code></td></tr><tr><td>边框颜色 / 粗细</td><td>搜索框边框</td><td><code>#F5F5F5</code>、粗细 <code>2</code></td></tr><tr><td>搜索框圆角 / 背景色</td><td>输入区域外观</td><td>圆角 <code>50</code>、背景 <code>#F8F8F8</code></td></tr><tr><td>显示更多</td><td>搜索栏右侧额外图标按钮</td><td>跳转菜单、消息等</td></tr><tr><td>更多区图标</td><td>更多按钮用字体或图片</td><td>同左侧逻辑</td></tr><tr><td>搜索框点击</td><td>点击输入区域跳转</td><td>跳转全站搜索页</td></tr><tr><td>更多按钮点击</td><td>点击更多图标跳转</td><td>个人中心、设置等</td></tr></tbody></table><h3 id="样式建议-3" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-3" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>首页顶栏：全宽、圆角 <strong>999</strong>（胶囊）、浅灰底，与轮播间距 <strong>16～24</strong> rpx</li><li>提示文字简短，点出可搜内容类型</li><li><strong>更多</strong> 入口适合放「扫码」「消息」等高频操作</li></ul><h3 id="使用技巧-注意事项-3" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-3" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li>搜索栏通常为 <strong>展示 + 跳转</strong>，实际搜索在目标搜索页完成</li><li>左侧 <strong>字体图标</strong> 与 <strong>图片</strong> 二选一，不要同时混用</li><li>若不需要右侧按钮，可将 <strong>按钮文字</strong> 留空或设与背景同色（以编辑器实际预览为准）</li><li>务必配置 <strong>搜索框点击</strong>，否则用户点击无反应</li></ul><hr><h2 id="筛选标签" tabindex="-1">筛选标签 <a class="header-anchor" href="#筛选标签" aria-label="Permalink to &quot;筛选标签&quot;">​</a></h2><p><strong>组件说明：</strong> 横向可滚动的标签栏，用于切换「推荐 / 最新 / 视频」等筛选项，并可联动下方列表或切换独立内容区。</p><h3 id="适用页面-4" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-4" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否可用</th><th>说明</th></tr></thead><tbody><tr><td>应用首页、功能页面</td><td>✅</td><td>可联动圈子列表或笔记列表</td></tr><tr><td>自定义页面</td><td>✅</td><td>视下方组件而定</td></tr><tr><td>社区圈子</td><td>✅</td><td><strong>仅</strong> 可与下方 <strong>笔记列表</strong> 联动</td></tr><tr><td>服务表单</td><td>❌</td><td></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">每页唯一</p><p>筛选标签 <strong>每页最多 1 个</strong>。圈子列表、笔记列表、瀑布流 <strong>三选一</strong>，详见 <a href="/features/ui-editor/page-types#互斥与唯一性规则">页面类型 — 互斥规则</a>。</p></div><h3 id="如何添加-4" tabindex="-1">如何添加 <a class="header-anchor" href="#如何添加-4" aria-label="Permalink to &quot;如何添加&quot;">​</a></h3><ol><li>左侧 <strong>布局导航 → 筛选标签</strong>（圈子页画布仅此项与笔记列表可用）</li><li>在筛选标签 <strong>下方</strong> 添加 <strong>笔记列表</strong> 或 <strong>圈子列表</strong>（首页二选一）</li><li>配置 <strong>下方内容模式</strong>、<strong>联动标识</strong>，并添加各 <strong>筛选项</strong></li></ol><h3 id="属性配置-4" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-4" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><h4 id="结构与联动" tabindex="-1">结构与联动 <a class="header-anchor" href="#结构与联动" aria-label="Permalink to &quot;结构与联动&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>滑动时吸顶</td><td>上滑时标签栏固定在导航栏下方</td><td>开启（默认）；关闭则随页滚动</td></tr><tr><td>下方内容模式</td><td>切换标签后下方如何变化</td><td><strong>列表 API 联动</strong> / <strong>Tab 独立内容区</strong></td></tr><tr><td>联动目标</td><td>联动的列表类型（首页）</td><td>圈子列表 / 笔记列表</td></tr><tr><td>联动标识</td><td>与下方列表组件的配对编号，一致才联动</td><td><code>default</code>（双方填相同值）</td></tr><tr><td>默认选中下标</td><td>进入页面默认选第几个标签</td><td><code>0</code>（第一项）</td></tr></tbody></table><p><strong>两种下方内容模式：</strong></p><table tabindex="0"><thead><tr><th>模式</th><th>适用场景</th><th>行为</th></tr></thead><tbody><tr><td>列表 API 联动</td><td>下方只有一个笔记/圈子列表</td><td>切换标签只改变列表的排序、筛选条件</td></tr><tr><td>Tab 独立内容区</td><td>每个标签下方内容完全不同</td><td>每个 Tab 可单独编排轮播、宫格、列表等</td></tr></tbody></table><h4 id="筛选项-每一项" tabindex="-1">筛选项（每一项） <a class="header-anchor" href="#筛选项-每一项" aria-label="Permalink to &quot;筛选项（每一项）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>显示文字</td><td>标签上看到的文案</td><td><code>推荐</code>、<code>最新</code>、<code>视频</code></td></tr><tr><td>取值</td><td>内部标识，可选</td><td>留空则用显示文字</td></tr><tr><td>排序字段（圈子）</td><td>联动圈子列表时的排序</td><td>智能热度、创建时间、人气等</td></tr><tr><td>排序方向（圈子）</td><td>升序 / 降序</td><td>降序（新/热在前）</td></tr><tr><td>圈子分类</td><td>只显示某分类下的圈子</td><td>留空=不限；可点 <strong>选择</strong></td></tr><tr><td>排序（笔记）</td><td>联动笔记列表时的排序</td><td>智能热度、最新、点赞、个性化推荐等</td></tr><tr><td>排序方向（笔记）</td><td>升序 / 降序</td><td>降序</td></tr><tr><td>圈子</td><td>只显示某圈子下的笔记（首页）</td><td>留空=不限；<strong>圈子页无此项</strong></td></tr><tr><td>话题</td><td>只显示某话题下的笔记</td><td>留空=不限</td></tr><tr><td>笔记类型</td><td>普通图文 / 视频 / 语音</td><td>不筛选 / 0 普通 / 1 视频 / 2 语音</td></tr><tr><td>闲置筛选 / 闲置类型</td><td>闲置交易相关筛选</td><td>按需</td></tr><tr><td>排除置顶</td><td>列表不显示置顶笔记</td><td>按需</td></tr><tr><td>前置图标 / 前置图片</td><td>标签左侧小图标</td><td>图片优先于图标</td></tr></tbody></table><h4 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性名</th><th>说明</th><th>常用值/示例</th></tr></thead><tbody><tr><td>选中背景 / 选中文字</td><td>当前标签药丸配色</td><td>品牌紫 <code>#9C5CFF</code> + 白字</td></tr><tr><td>未选中背景 / 未选中文字</td><td>未选中标签配色</td><td>灰底 <code>#F2F2F2</code> + 深灰字</td></tr><tr><td>显示指示条</td><td>选中项底部短横条</td><td>开启</td></tr><tr><td>指示条宽 / 高 / 圆角 / 间距</td><td>底部指示条细节</td><td>宽 <code>48</code>、高 <code>6</code></td></tr><tr><td>字号 / 行高 / 字间距</td><td>标签文字排版</td><td><code>26</code>、行高 <code>1.35</code></td></tr><tr><td>项间距</td><td>标签之间的空隙</td><td><code>12</code></td></tr><tr><td>药丸圆角 / 内边距</td><td>标签胶囊形状</td><td>圆角 <code>999</code>、左右内边距 <code>28</code></td></tr><tr><td>滚动区左右内边距</td><td>整行标签左右留白</td><td><code>24</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">圈子页特别说明</p><p>在 <strong>社区圈子</strong> 页面，筛选标签 <strong>只能</strong> 与下方 <strong>笔记列表</strong> 联动，不能联动圈子列表。联动目标会自动固定为笔记列表；筛选项中 <strong>不会出现「按圈子筛选」</strong>（当前已在某一圈子内）。联动标识仍须与笔记列表组件填 <strong>相同值</strong>。</p></div><h3 id="样式建议-4" tabindex="-1">样式建议 <a class="header-anchor" href="#样式建议-4" aria-label="Permalink to &quot;样式建议&quot;">​</a></h3><ul><li>吸顶开启时，标签栏背景建议设 <strong>纯白或半透明</strong>，避免滚动时内容穿透</li><li>标签数量 <strong>4～8 个</strong> 为宜，过多靠横向滑动</li><li>选中态用品牌主色，未选中用浅灰，对比清晰</li></ul><h3 id="使用技巧-注意事项-4" tabindex="-1">使用技巧 / 注意事项 <a class="header-anchor" href="#使用技巧-注意事项-4" aria-label="Permalink to &quot;使用技巧 / 注意事项&quot;">​</a></h3><ul><li><strong>列表 API 联动</strong>：筛选标签与笔记/圈子列表的 <strong>联动标识必须一致</strong>（默认都是 <code>default</code>）</li><li>首页画布上 <strong>圈子列表与笔记列表只能存在一个</strong>，请先决定联动哪一种</li><li><strong>Tab 独立内容区</strong>：在属性 <strong>选项</strong> 里点标签名切换当前 Tab，再向画布添加该 Tab 下方组件；手机预览内 Tab <strong>不可点击</strong>（避免无法选中组件）</li><li><strong>个性化推荐</strong> 排序需后台开启推荐能力；不可用时会自动降级为智能热度</li><li>筛选项的排序、分类等仅在 <strong>列表 API 联动</strong> 且联动目标匹配时生效</li><li>组件外层宽高、背景、阴影等请在 <strong>样式</strong> Tab 配置（与画布其他组件相同）</li></ul><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续阅读 <a href="/features/ui-editor/components-display">信息展示组件</a> — 列表、通知栏、结束文本。</p>',82)])])}const u=d(e,[["render",n]]);export{b as __pageData,u as default};
